// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IVaultFeeOracleQuery} from "contracts/interfaces/IVaultFeeOracleQuery.sol";
import {IStandardVault} from "contracts/interfaces/IStandardVault.sol";
import {AddressSet, AddressSetRepo} from '@crane/contracts/utils/collections/sets/AddressSetRepo.sol';
import {Bytes4Set, Bytes4SetRepo} from "@crane/contracts/utils/collections/sets/Bytes4SetRepo.sol";
import {BetterAddress} from "@crane/contracts/utils/BetterAddress.sol";
import {BetterEfficientHashLib} from "@crane/contracts/utils/BetterEfficientHashLib.sol";
// import {MultiAssetBasicVaultRepo} from "contracts/vaults/basic/MultiAssetBasicVaultRepo.sol";

library StandardVaultRepo {
    using AddressSetRepo for AddressSet;
    // using BetterAddress for address[];
    using Bytes4SetRepo for Bytes4Set;
    using BetterEfficientHashLib for bytes;

    bytes32 internal constant STORAGE_SLOT = keccak256("indexedex.vaults.standard.vault");

    // TODO Add mapping for underlying decimals.
    struct Storage {
        IVaultFeeOracleQuery feeOracle;
        bytes32 vaultFeeTypeIds;
        bytes32 contentsId;
        Bytes4Set vaultTypes;
        mapping(address token => uint8 decimals) decimalOfToken;
    }

    function _layout(bytes32 slot) internal pure returns (Storage storage layoutStruct) {
        assembly {
            layoutStruct.slot := slot
        }
    }

    function _layout() internal pure returns (Storage storage layoutStruct) {
        return _layout(STORAGE_SLOT);
    }

    function _initialize(
        Storage storage layoutStruct,
        IVaultFeeOracleQuery feeOracle,
        bytes32 vaultFeeTypeIds,
        bytes4[] memory vaultTypes,
        bytes32 contentsId
    ) internal {
        // _initPermit2Aware(permit2);
        layoutStruct.feeOracle = feeOracle;
        layoutStruct.vaultFeeTypeIds = vaultFeeTypeIds;
        layoutStruct.vaultTypes._add(vaultTypes);
        // layoutStruct.contentsId = abi.encode(vaultTokens)._hash();
        layoutStruct.contentsId = contentsId;
        // MultiAssetBasicVaultRepo._addVaultTokens(vaultTokens);
    }

    function _initialize(
        IVaultFeeOracleQuery feeOracle,
        bytes32 vaultFeeTypeIds,
        bytes4[] memory vaultTypes,
        bytes32 contentsId
    ) internal {
        _initialize(_layout(), feeOracle, vaultFeeTypeIds, vaultTypes, contentsId);
    }

    function _feeOracle(Storage storage layoutStruct) internal view returns (IVaultFeeOracleQuery) {
        return layoutStruct.feeOracle;
    }

    function _feeOracle() internal view returns (IVaultFeeOracleQuery) {
        return _feeOracle(_layout());
    }

    function _vaultFeeTypeIds(Storage storage layoutStruct) internal view returns (bytes32) {
        return layoutStruct.vaultFeeTypeIds;
    }

    function _vaultFeeTypeIds() internal view returns (bytes32) {
        return _vaultFeeTypeIds(_layout());
    }

    function _vaultTypes(Storage storage layoutStruct) internal view returns (bytes4[] memory vaultTypes_) {
        return layoutStruct.vaultTypes._values();
    }

    function _vaultTypes() internal view returns (bytes4[] memory vaultTypes_) {
        return _vaultTypes(_layout());
    }

    function _contentsId(Storage storage layoutStruct) internal view returns (bytes32) {
        return layoutStruct.contentsId;
    }

    function _contentsId() internal view returns (bytes32) {
        return _contentsId(_layout());
    }
}

contracts/vaults/detf/common/core/DETFBo.content:
// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {ONE_WAD} from "@crane/contracts/constants/Constants.sol";

import {IDETFNFTVault} from "contracts/interfaces/IDETFNFTVault.sol";
import {BondTerms} from "contracts/interfaces/VaultFeeTypes.sol";
import {StandardVaultRepo} from "contracts/vaults/standard/StandardVaultRepo.sol";

library DETFBondNFTMathLib {
    enum LockDurationStatus {
        Valid,
        TooShort,
        TooLong
    }

    function _calcBonusMultiplier(BondTerms memory terms_, uint256 lockDuration_)
        internal
        pure
        returns (uint256 bonusMultiplier_)
    {
        if (terms_.maxLockDuration <= terms_.minLockDuration) {
            return ONE_WAD + terms_.maxBonusPercentage;
        }

        uint256 normalized =
            ((lockDuration_ - terms_.minLockDuration) * ONE_WAD) / (terms_.maxLockDuration - terms_.minLockDuration);
        uint256 curveFactor = (normalized * normalized) / ONE_WAD;

        uint256 bonus;
        if (terms_.maxBonusPercentage >= terms_.minBonusPercentage) {
            bonus = terms_.minBonusPercentage + ((terms_.maxBonusPercentage - terms_.minBonusPercentage) * curveFactor)
                / ONE_WAD;
        } else {
            bonus = terms_.maxBonusPercentage;
        }

        bonusMultiplier_ = ONE_WAD + bonus;
    }

    function _bondTerms(address vault_) internal view returns (BondTerms memory terms_) {
        terms_ = StandardVaultRepo._feeOracle().bondTermsOfVault(vault_);
    }

    function _bonusMultiplierOfVault(address vault_, uint256 lockDuration_)
        internal
        view
        returns (uint256 bonusMultiplier_)
    {
        bonusMultiplier_ = _calcBonusMultiplier(_bondTerms(vault_), lockDuration_);
    }

    function _position(
        uint256 originalShares_,
        uint256 effectiveShares_,
        uint256 bonusMultiplier_,
        uint256 unlockTime_,
        uint256 rewardDebt_
    ) internal pure returns (IDETFNFTVault.Position memory position_) {
        position_ = IDETFNFTVault.Position({
            originalShares: originalShares_,
            effectiveShares: effectiveShares_,
            bonusMultiplier: bonusMultiplier_,
            unlockTime: unlockTime_,
            rewardDebt: rewardDebt_
        });
    }

    function _lockDurationStatus(BondTerms memory terms_, uint256 lockDuration_)
        internal
        pure
        returns (LockDurationStatus status_)
    {
        if (lockDuration_ < terms_.minLockDuration) {
            return LockDurationStatus.TooShort;
        }

        if (lockDuration_ > terms_.maxLockDuration) {
            return LockDurationStatus.TooLong;
        }

        return LockDurationStatus.Valid;
    }

    function _calcHarvestRewards(uint256 effectiveShares_, uint256 rewardPerShares_, uint256 paidPerShare_)
        internal
        pure
        returns (uint256 rewards_, bool hasRewards_)
    {
        if (rewardPerShares_ <= paidPerShare_) {
            return (0, false);
        }

        rewards_ = (effectiveShares_ * (rewardPerShares_ - paidPerShare_)) / ONE_WAD;
        hasRewards_ = rewards_ > 0;
    }

    function _calcEffectiveShares(uint256 shares_, uint256 bonusMultiplier_)
        internal
        pure
        returns (uint256 effectiveShares_)
    {
        effectiveShares_ = (shares_ * bonusMultiplier_) / ONE_WAD;
    }

    function _isDeadlineExceeded(uint256 deadline_, uint256 currentTimestamp_) internal pure returns (bool) {
        return currentTimestamp_ > deadline_;
    }

    function _isUnlockPending(uint256 unlockTime_, uint256 currentTimestamp_) internal pure returns (bool) {
        return currentTimestamp_ < unlockTime_;
    }

    function _isCallerOwner(address owner_, address caller_) internal pure returns (bool) {
        return owner_ == caller_;
    }

    function _validateRedeemCaller(address caller_, address recipient_, address detf_, address owner_)
        internal
        pure
        returns (bool)
    {
        if (owner_ == caller_) {
            return true;
        }

        if (caller_ == detf_ && recipient_ == owner_) {
            return true;
        }

        return false;
    }
}

