    // end::FunctionNotPresent(bytes4)[]

    // tag::FacetNotPresent(address)[]
    error FacetNotPresent(address facet);
    // end::FacetNotPresent(address)[]

    // tag::SelectorFacetMismatch(bytes4-address-address)[]
