        log(logMsg);
        log(DIV);
        console.logBytes(data);
        log(DIV);
    }

    function log(string memory logMsg, bytes4[] memory values) public pure {
        log(logMsg);
        log("values length = ", values.length);
        log(DIV);
        for (uint256 i = 0; i < values.length; i++) {
            console.logBytes4(values[i]);
        }
        log(DIV);
    }

