// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import {
    BondTerms,

    // DexTerms,
    // KinkLendingTerms,
    VaultFeeType
} from "contracts/interfaces/VaultFeeTypes.sol";
import {IFeeCollectorProxy} from "contracts/interfaces/proxies/IFeeCollectorProxy.sol";

/**
 * @title IVaultFeeOracleQuery
 * @notice Interface for querying the vault fee oracle.
 * @notice All fee percentages are denominated in WAD (1e18 = 100%).
 * @notice 1e15  = 0.1%
 * @notice 1e16  = 1%
 * @notice 5e16  = 5%
 * @notice 1e17  = 10%
 * @notice 1e18  = 100%
 * @notice Fee resolution follows a three-tier fallback: vault-specific -> vault-type default -> global default.
 * @notice A stored value of 0 means "unset" and triggers fallback to the next tier.
 * @notice Setting an explicit 0% fee for a specific vault or type is not supported; 0 always means "use default".
 * @custom:interfaceid 0xc6a03847
 */
// TODO Change fee queries to mapping by vault type as interface ID.
interface IVaultFeeOracleQuery {
    /* ---------------------------------------------------------------------- */
    /*                                 Errors                                 */
    /* ---------------------------------------------------------------------- */

    /* ---------------------------------------------------------------------- */
    /*                                 Events                                 */
    /* ---------------------------------------------------------------------- */

    /* ---------------------------------------------------------------------- */
    /*                                Functions                               */
    /* ---------------------------------------------------------------------- */

    /**
     * @custom:selector 0x017e7e58
     */
    function feeTo() external view returns (IFeeCollectorProxy feeTo_);

    // function tokens() external view returns (address[] memory tokens_);

    /* ---------------------------------------------------------------------- */
    /*                               Usage Terms                              */
    /* ---------------------------------------------------------------------- */

    function usageFeeVaultTypeIds() external view returns (bytes4[] memory vaultTypeIds_);

    function defaultUsageFee() external view returns (uint256 defaultFee_);

    function defaultUsageFeeOfTypeId(bytes4 vaultFeeTypeId) external view returns (uint256 defaultFee_);

    function usageFeeOfVault(address vault) external view returns (uint256 usageFee_);

    function usageFeeAndFeeToOfVault(address vault) external view returns (IFeeCollectorProxy feeTo, uint256 usageFee_);

    /* ---------------------------------------------------------------------- */
    /*                                DEX Terms                               */
    /* ---------------------------------------------------------------------- */

    /* ----------------------------- Swap Terms ----------------------------- */

    function dexSwapFeeVaultTypeIds() external view returns (bytes4[] memory vaultTypeIds_);

    // function defaultDexTerms() external view returns (DexTerms memory dexTerms_);

    function defaultDexSwapFee() external view returns (uint256 swapFee_);

    // function defaultDexTermsOfTypeId(bytes4 vaultFeeTypeId) external view returns (DexTerms memory dexTerms_);

    function defaultDexSwapFeeOfTypeId(bytes4 vaultFeeTypeId) external view returns (uint256 swapFee_);

    // function dexTermsOfVault(address vault) external view returns (DexTerms memory dexTerms_);

    function dexSwapFeeOfVault(address vault) external view returns (uint256 swapFee_);

    // function dexTermsAndFeeToOfVault(address vault) external view returns (address feeTo, DexTerms memory dexTerms_);

    function dexSwapFeeAndFeeToOfVault(address vault) external view returns (IFeeCollectorProxy feeTo, uint256 swapFee_);

    /* ---------------------------------------------------------------------- */
    /*                               Bond Terms                               */
    /* ---------------------------------------------------------------------- */

    function bondVaultTypesIds() external view returns (bytes4[] memory vaultTypeIds_);

    function defaultBondTerms() external view returns (BondTerms memory bondTerms_);

    function defaultBondTermsOfVaultTypeId(bytes4 vaultFeeTypeId) external view returns (BondTerms memory bondTerms_);

    function bondTermsOfVault(address vault) external view returns (BondTerms memory bondTerms_);

    function bondTermsAndFeeToOfVault(address vault)
        external
        view
        returns (IFeeCollectorProxy feeTo, BondTerms memory bondTerms_);

    /* -------------------------------------------------------------------------- */
    /*                              Seigniorage Terms                             */
    /* -------------------------------------------------------------------------- */

    function seigniorageVaultTypeIds() external view returns (bytes4[] memory vaultTypeIds_);

    function defaultSeigniorageIncentivePercentage() external view returns (uint256 percentage);

    function seigniorageIncentivePercentageOfTypeId(bytes4 vaultTypeId) external view returns (uint256 percentage);

    function seigniorageIncentivePercentageOfVault(address vault) external view returns (uint256 percentage);

    function seigniorageIncentivePercentageOfVaultAndFeeTo(address vault)
        external
        view
        returns (IFeeCollectorProxy feeTo, uint256 percentage);

    /// @notice Global default `f` (feeTo effective-share weight of the pot). WAD. Stored 0 = unset.
    function defaultSeigniorageFeeToSharePercentage() external view returns (uint256 percentage);

    /// @notice Type-level `f`. Stored 0 = unset (fallback to global).
    function seigniorageFeeToSharePercentageOfTypeId(bytes4 vaultTypeId) external view returns (uint256 percentage);

    /// @notice Effective `f` for `vault` after three-tier resolution.
    function seigniorageFeeToSharePercentageOfVault(address vault) external view returns (uint256 percentage);

    /// @notice Global default `c` (creator effective-share weight of the pot). WAD. Stored 0 = unset.
    function defaultSeigniorageCreatorSharePercentage() external view returns (uint256 percentage);

    /// @notice Type-level `c`. Stored 0 = unset (fallback to global).
    function seigniorageCreatorSharePercentageOfTypeId(bytes4 vaultTypeId) external view returns (uint256 percentage);

    /// @notice Effective `c` for `vault` after three-tier resolution.
    function seigniorageCreatorSharePercentageOfVault(address vault) external view returns (uint256 percentage);

    /// @notice `(p, f, c)` for `vault` after three-tier resolution.
    function seigniorageSplitOfVault(address vault)
        external
        view
        returns (uint256 p, uint256 f, uint256 c);

    /// @notice `(feeTo, p, f, c)` for `vault` after three-tier resolution.
    function seigniorageSplitAndFeeToOfVault(address vault)
        external
        view
        returns (IFeeCollectorProxy feeTo, uint256 p, uint256 f, uint256 c);

    /// @notice Bond terms plus `(feeTo, p, f, c)` in one call.
    function bondTermsAndSeigniorageOfVault(address vault)
        external
        view
        returns (IFeeCollectorProxy feeTo, BondTerms memory terms, uint256 p, uint256 f, uint256 c);

    /* -------------------------------------------------------------------------- */
    /*                         Liquid reserve policy (WAD)                        */
    /* -------------------------------------------------------------------------- */

    /// @notice Global default fraction of total reserve that should remain liquid (WETH sleeve).
    /// @dev WAD: 1e18 = 100%. Stored 0 = unset (fallback).
    function defaultLiquidReservePercentage() external view returns (uint256 percentage);

    /// @notice Type-level default (vault fee / marker interface id).
    function defaultLiquidReservePercentageOfTypeId(bytes4 vaultTypeId) external view returns (uint256 percentage);

    /// @notice Effective liquid-reserve target for `vault` after three-tier resolution.
    function liquidReservePercentageOfVault(address vault) external view returns (uint256 percentage);

    function liquidReservePercentageOfVaultAndFeeTo(address vault)
        external
        view
        returns (IFeeCollectorProxy feeTo, uint256 percentage);

    /* ---------------------------------------------------------------------- */
    /*                              Lending Terms                             */
    /* ---------------------------------------------------------------------- */

    // function lendingVaultTypeIds() external view returns (bytes4[] memory vaultTypeIds_);

    // function defaultLendingTerms() external view returns (KinkLendingTerms memory defaultKinkLendingTerms_);

    // function defaultLendingTermsOfTypeId(bytes3 vaultTypeId) external view returns (KinkLendingTerms memory lendingTerms_);

    // function lendingTermsOfVault(address vault) external view returns (KinkLendingTerms memory lendingTerms_);

    // function lendingTermsAndFeeToOfVault(address vault) external view returns (address feeTo, KinkLendingTerms memory lendingTerms_);

    /* ---------------------------------------------------------------------- */

    // /**
    //  * @custom:selector 0x103b33f7
    //  */
    // function defaultVaultFee() external view returns (uint256 vaultFee_);

    // function defaultFeeOfVaultType(bytes4 vaultFeeTypeId) external view returns (uint256 defaultFee);

    // /**
    //  * @custom:selector 0x3eecaf4d
    //  */
    // function defaultDexFee() external view returns (uint256 dexFee_);

    // function defaultDDexFeeOfType(bytes4 vaultFeeTypeId) external view returns (uint256 dexFee_);

    // /**
    //  * @custom:selector 0x7498884e
    //  */
    // function defaultLendingFee() external view returns (uint256 lendingFee_);

    // function defaultLendingFeeOfVaultType(bytes4 vaultFeeTypeId) external view returns (uint256 lendingFee_);

    // /**
    //  * @custom:selector 0xc33b8137
    //  */
    // function feeOfVault(address vault) external view returns (uint256 vaultFee_);

    // function vaultTypeIds() external view returns (bytes4[] memory vaultTypeIds_);

    // /**
    //  * @custom:selector 0x70486640
    //  */
    // function dexVaults() external view returns (address[] memory dexVaults_);

    // /**
    //  * @custom:selector 0xf17a0eba
    //  */
    // function isDexVault(address vault) external view returns (bool isDexVault_);

    // function bondVaults() external view returns (address[] memory bondVaults_);

    // function isBondVault(address vault) external view returns (bool isBondVault_);

    // /**
    //  * @custom:selector 0x2a194b16
    //  */
    // function lendingVaults() external view returns (address[] memory lendingVaults_);

    // /**
    //  * @custom:selector 0xb1490563
    //  */
    // function isLendingVault(address vault) external view returns (bool isLendingVault_);
}

contracts/interfaces/IDETFNFTVault.sol.content:
// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

/* -------------------------------------------------------------------------- */
/*                                    Crane                                   */
/* -------------------------------------------------------------------------- */

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IERC721} from "@crane/contracts/interfaces/IERC721.sol";

/* -------------------------------------------------------------------------- */
/*                                  Indexedex                                 */
/* -------------------------------------------------------------------------- */

import {IDetf} from "contracts/interfaces/detf/IDetf.sol";
import {IDetfSelfNftInventoryPolicy} from "contracts/vaults/detf/common/inventory/IDetfSelfNftInventoryPolicy.sol";

/**
 * @title IDETFNFTVault
 * @author cyotee doge <not_cyotee@proton.me>
 * @notice Interface for Protocol NFT Vault managing bond positions.
 * @dev Each NFT represents a bonded position with:
 *      - Original shares (base LP allocation)
 *      - Effective shares (boosted by lock duration)
 *      - Unlock time (when position can be redeemed)
 *      - Reward-token rewards (accumulated from protocol seigniorage and vault-held rewards)
 *
 *      The protocol-owned NFT has no unlock time and accumulates LP
 *      from sold user NFTs. The protocol NFT and feeTo-owned NFTs are never sold.
 */
interface IDETFNFTVault is IERC721, IDetfSelfNftInventoryPolicy {
    /* ---------------------------------------------------------------------- */
    /*                              Structs                                   */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Bond position data.
     */
    struct Position {
        uint256 originalShares; // Base LP allocation
        uint256 effectiveShares; // Boosted shares for reward calculation
        uint256 bonusMultiplier; // Lock duration bonus (1e18 = 1x)
        uint256 unlockTime; // Timestamp when position unlocks
        uint256 rewardDebt; // Reward debt for calculating pending rewards
    }

    /// @notice Lock view surface for a bond position (facet-registered).
    struct LockInfo {
        uint256 sharesAwarded;
        uint256 rewardPerShare;
        uint256 bonusPercentage;
        uint256 unlockTime;
    }

    /* ---------------------------------------------------------------------- */
    /*                              View Functions                            */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Returns the DETF diamond.
     * @return The DETF diamond
     */
    function detf() external view returns (IDetf);

    /**
     * @notice Returns the LP token (BPT from reserve pool).
     * @return The LP token
     */
    function lpToken() external view returns (IERC20);

    /**
     * @notice Returns the reward token.
     * @return The reward token for this vault's accrual model.
     */
    function rewardToken() external view returns (IERC20);

    /**
     * @notice Returns the total effective shares across all positions.
     * @return Total effective shares
     */
    function totalShares() external view returns (uint256);

    /**
     * @notice Returns the protocol-owned NFT token ID.
     * @return The protocol NFT token ID
     */
    function detfNFTId() external view returns (uint256);

    /**
     * @notice Returns the position data for a token ID.
     * @param tokenId The NFT token ID
     * @return position The position data
     */
    function positionOf(uint256 tokenId) external view returns (Position memory position);

    /**
     * @notice Returns the position data for a token ID (alias for positionOf).
     * @param tokenId The NFT token ID
     * @return position The position data
     */
    function getPosition(uint256 tokenId) external view returns (Position memory position);

    /**
     * @notice Returns the original shares for a token ID.
     * @param tokenId The NFT token ID
     * @return shares Original shares
     */
    function originalSharesOf(uint256 tokenId) external view returns (uint256 shares);

    /**
     * @notice Sum of originalShares across all tokenIds (user + protocol).
     */
    function totalOriginalShares() external view returns (uint256 shares);

    /**
     * @notice Returns the effective shares for a token ID.
     * @param tokenId The NFT token ID
     * @return shares Effective shares
     */
    function effectiveSharesOf(uint256 tokenId) external view returns (uint256 shares);

    /**
     * @notice Returns the unlock time for a token ID.
     * @param tokenId The NFT token ID
     * @return unlockTime Unlock timestamp
     */
    function unlockTimeOf(uint256 tokenId) external view returns (uint256 unlockTime);

    /**
     * @notice Checks if a position is unlocked.
     * @param tokenId The NFT token ID
     * @return unlocked True if position can be redeemed
     */
    function isUnlocked(uint256 tokenId) external view returns (bool unlocked);

    /**
     * @notice Returns pending reward-token rewards for a token ID.
     * @param tokenId The NFT token ID
     * @return pending Amount of pending reward-token rewards.
     */
    function pendingRewards(uint256 tokenId) external view returns (uint256 pending);

    /**
     * @notice Returns lock info for a position.
     */
    function lockInfoOf(uint256 tokenId) external view returns (LockInfo memory info);

    /**
     * @notice Returns the global accumulated reward per effective share.
     */
    function rewardPerShares() external view returns (uint256);

    /**
     * @notice Converts LP amount to shares.
     * @param lpAmount Amount of LP tokens
     * @return shares Equivalent shares
     */
    function convertToShares(uint256 lpAmount) external view returns (uint256 shares);

    /**
     * @notice Converts shares to LP amount.
     * @param shares Amount of shares
     * @return lpAmount Equivalent LP tokens
     */
    function convertToAssets(uint256 shares) external view returns (uint256 lpAmount);

    /**
     * @notice Owner (DETF) transfers a foreign ERC-20 held by this vault (e.g. reserve LP).
     * @dev Used for physical LP custody: bond NFT holds user reserve LP; DETF may pull on
     *      maturity close / sell-to-protocol migration.
     */
    function transferHeldToken(IERC20 token, address to, uint256 amount) external;

    /* ---------------------------------------------------------------------- */
    /*                          Position Management                           */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Creates a new bond position.
     * @dev Called by the DETF diamond during bonding.
     * @param lpAmount Amount of LP tokens to bond
     * @param lockDuration Duration to lock in seconds
     * @param recipient Address to receive the NFT
     * @return tokenId The minted NFT token ID
     */
    function createPosition(uint256 lpAmount, uint256 lockDuration, address recipient)
        external
        returns (uint256 tokenId);

    /// @notice Open bond with LP principal + separate reward-weight base (before lock bonus).
    /// @param originalShares Fungible LP principal (sell/close unwind units).
    /// @param effectiveBase Reward weight base before lock bonus (e.g. rateAsset mid WAD).
    function createPositionWithEffectiveBase(
        uint256 originalShares,
        uint256 effectiveBase,
        uint256 lockDuration,
        address recipient
    ) external returns (uint256 tokenId);

    /// @notice Mints and records the protocol-owned NFT (once).
    /// @dev Expected to be called during package post-deploy/initialization.
    ///      L6: wired-state is `reservedBondNftsWired` / protocol-nft-initialized, not `id == 0`.
    function initializeDETFNFT() external returns (uint256 tokenId);

    /// @notice D7: mint ids 0, 1, 2 (protocol / feeTo / creator) before any user bond.
    /// @dev `creator == 0` mints id 2 to `feeTo` (D21).
    function initializeReservedBondNfts(address feeTo, address creator) external returns (uint256 protocolId);

    /// @notice L6 wired sentinel. Not `detfNftId == 0`.
    function reservedBondNftsWired() external view returns (bool);

    /// @notice L7: add effective-share weight only on ids 1 or 2. Does not change `originalShares`.
    function addEffectiveSharesOnly(uint256 tokenId, uint256 shares) external;

    /**
     * @notice Redeems a position after unlock.
     * @param tokenId The NFT token ID
     * @param recipient Address to receive the extracted value and rewards
     * @param deadline Route deadline (reverts if exceeded)
     * @return wethOut Amount of WETH extracted and sent to `recipient`
     */
    function redeemPosition(uint256 tokenId, address recipient, uint256 deadline) external returns (uint256 wethOut);

    /// @notice Harvest, debit the position, and burn a mature user NFT without selling into id 0.
    /// @dev D25 close: DETF then proportionally withdraws LP and burns the DETF self-leg.
    function retireMaturePosition(uint256 tokenId, address rewardsRecipient)
        external
        returns (uint256 originalShares, uint256 rewardsClaimed);

    /**
     * @notice Claims reward-token rewards without redeeming position.
     * @param tokenId The NFT token ID
     * @param recipient Address to receive rewards
     * @return rewards Amount of reward-token rewards claimed.
     */
    function claimRewards(uint256 tokenId, address recipient) external returns (uint256 rewards);

    /* ---------------------------------------------------------------------- */
    /*                         Bond NFT → rebasing claim sale                         */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Sells a user bond NFT position into the protocol-owned position.
     * @dev Intended to be called by the DETF diamond (owner) when a user invokes
     *      the canonical Bond NFT → rebasing claim token route.
     *
     *      Semantics:
     *      - Harvest pending reward-token rewards and send them to `rewardsRecipient`.
     *      - Transfer principal-only shares (`originalShares`) into the protocol NFT.
     *      - Burn the sold bond NFT.
     *
     * @param tokenId The user bond NFT tokenId to sell.
     * @param seller The expected owner of `tokenId`.
     * @param rewardsRecipient Address to receive harvested rewards.
     * @return principalShares Principal-only shares contributed to the protocol NFT.
     * @return rewardsClaimed Amount of reward-token rewards claimed.
     */
    function sellPositionToDetfNft(uint256 tokenId, address seller, address rewardsRecipient)
        external
        returns (uint256 principalShares, uint256 rewardsClaimed);

    /* ---------------------------------------------------------------------- */
    /*                          Protocol NFT Operations                       */
    /* ---------------------------------------------------------------------- */

    /**
     * @notice Adds LP to the protocol-owned NFT.
     * @dev Called when users sell their NFTs to the protocol.
     *      Does not reset lock time or affect rewards.
     * @param tokenId The protocol NFT token ID
     * @param lpAmount Amount of LP tokens to add
     */
    function addToDETFNFT(uint256 tokenId, uint256 lpAmount) external;

    /**
     * @notice Debits LP from the protocol-owned NFT 1:1 (original and effective).
     * @dev onlyOwner. `tokenId` must be `detfNFTId`. Inverse of `addToDETFNFT`.
