    function deploy(IDiamondFactoryPackage pkg, bytes memory pkgArgs) external returns (address proxy);
    // end::deploy(IDiamondFactoryPackage,bytes)[]

    // tag::initAccount(IDiamondFactoryPackage,bytes)[]
