        // Find the correct insertion point using binary search
        uint256 left = 1; // 1-indexed
        uint256 right = set.values.length;

        while (left <= right) {
            uint256 mid = (left + right) / 2;
            if (set.values[mid - 1] < addr) {
                left = mid + 1;
            } else {
                right = mid - 1;
