interface IStandardExchangeOut is IStandardExchangeErrors {
    struct OutArgs {
        IERC20 tokenIn;
        uint256 maxAmountIn;
        IERC20 tokenOut;
        uint256 amountOut;
        address recipient;
        bool pretransferred;
