    /* -------------------------------------------------------------------------- */
    /*                                   Errors                                   */
    /* -------------------------------------------------------------------------- */

    // tag::IsLocked()[]
    /**
     * @notice Thrown when a reentrant call is attempted while the lock is held.
     */
