    function _quickSort(Bytes4Set storage set, int256 left, int256 right) private {
        if (left >= right) return;

        bytes4[] storage values = set.values;
        int256 i = left;
        int256 j = right;
        bytes4 pivot = values[uint256(left + (right - left) / 2)];

        while (i <= j) {
