    // end::IsLocked()[]

    /* -------------------------------------------------------------------------- */
    /*                                  Functions                                 */
    /* -------------------------------------------------------------------------- */

    // tag::isLocked()[]
    /// @notice Returns whether reentrancy lock is currently active.
    /// @return locked_ True if locked (reentrancy will be blocked), false otherwise.
    function isLocked() external view returns (bool locked_);
